begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Your Girl Friday Pet Sitting Services", "category": "Pet Services", "city": "Tracy", "address": null, "phone": "(209) 814-7200", "website": "https://www.rachelyourgirlfriday.com/", "source_url": "https://www.rachelyourgirlfriday.com/faq", "duplicate_key": "rachelyourgirlfriday.com", "areas": ["Tracy"], "tags": ["pet sitting", "dog walking"], "description": "In-home pet sitting and dog walking in Tracy. The official FAQ limits its regular service area to Tracy; Mountain House appointments are conditional on scheduling and are not established coverage here. Overnight visits depend on availability. Confirm your pet needs, dates, total quote, holiday and short-notice fees directly. No visitable office established.", "note": "First-party website information checked November 13, 2026 with fresh HTTP200 homepage, FAQ and contact page. Checked business identity, public call/text2098147200, advertised in-home sitting/walking, Tracy-only regular coverage and conditional outside-area limits. FAQ advertises holiday, late-evening and short-notice surcharges; no fixed quote, booking, holiday availability or cancellation guarantee adopted. Medication capability, credentials, insurance, background checks, quality and safety not independently validated. No provider photos, testimonials or Yelp reviews/ratings copied. Sources: https://www.rachelyourgirlfriday.com/ https://www.rachelyourgirlfriday.com/faq https://www.rachelyourgirlfriday.com/contact"}]'::jsonb) loop
 if exists(select 1 from public.businesses where lower(name)=lower(r->>'name') or website ilike '%'||(r->>'duplicate_key')||'%' or (r->>'phone' is not null and right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10))) then raise exception 'Duplicate requires individual review: %',r->>'name'; end if;
 insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values(r->>'name',r->>'category',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now()) returning id into bid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','address conflicts or limits'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
 select to_jsonb(b) into applied from public.businesses b where id=bid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'Individually source-checked directory expansion; no seed publication',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.city,b.verified_at,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.website='https://www.rachelyourgirlfriday.com/';
